86	    public static String encodePoints(List<Point> points) {
87	        StringBuilder sb = new StringBuilder();
88	        for (int i = 0; i < points.size(); i++) {
89	            if (i > 0) {
90	                sb.append(';');
91	            }
92	            sb.append(points.get(i).x()).append(',').append(points.get(i).y());
93	        }
94	        return sb.toString();
95	    }
96	
97	    /** 点列表解码。 */
98	    public static List<Point> decodePoints(String text) {
99	        List<Point> points = new ArrayList<>();
100	        if (text != null && !text.isEmpty()) {
101	            for (String pair : text.split(";")) {
102	                String[] xy = pair.split(",");
103	                points.add(new Point(Integer.parseInt(xy[0]), Integer.parseInt(xy[1])));
104	            }
105	        }
106	        return points;
107	    }
108	
109	    /** zoneId 列表编码（字典序去重由调用方保证），逗号拼接。 */
110	    public static String encodeZoneIds(List<String> zoneIds) {
111	        return String.join(",", zoneIds);
112	    }
113	
114	    /** zoneId 列表解码，空串返回空列表。 */
115	    public static List<String> decodeZoneIds(String text) {
116	        if (text == null || text.isEmpty()) {
117	            return new ArrayList<>();
118	        }
119	        return new ArrayList<>(Arrays.asList(text.split(",")));
120	    }
121	}
