527	    @Test
528	    void concurrentSameRequestIdPlaysBackOneOutcome() throws Exception {
529	        // 同键同参并发：只能有一次业务生效，另一方重放同一结果
530	        String requestId = "concurrent-same-key";
531	        int n = 6;
532	        CyclicBarrier barrier = new CyclicBarrier(n);
533	        ExecutorService pool = Executors.newFixedThreadPool(n);
534	        try {
535	            List<Future<MutationResponse>> futures = new java.util.ArrayList<>();
536	            for (int i = 0; i < n; i++) {
537	                futures.add(pool.submit(() -> {
538	                    barrier.await(5, TimeUnit.SECONDS);
539	                    return service.createZone(
540	                            new ZoneCreateRequest("ck", 0, 0, 10, 10, requestId));
541	                }));
